const tabs=[...document.querySelectorAll('[data-platform]')];function selectPlatform(index){const tab=tabs[index],item=platforms[tab.dataset.platform];tabs.forEach((t,i)=>{t.setAttribute('aria-selected',String(i===index));t.tabIndex=i===index?0:-1;});document.getElementById('platform-panel').setAttribute('aria-labelledby',tab.id);for(const field of ['kind','title','copy','scope'])document.getElementById('platform-'+field).textContent=item[field];document.getElementById('platform-preview').innerHTML=item.img?`<button data-evidence="${item.key}" aria-label="查看平台证据原图"><img src="assets/${item.img}" alt="${item.alt}"><span>查看原图 ＋</span></button>`:`<div class="empty-evidence"><strong>代表作品待补充</strong><span>内容与数据证据位置</span></div>`;if(!reduced.matches)document.getElementById('platform-panel').animate([{opacity:.2,transform:'translateY(8px)'},{opacity:1,transform:'none'}],{duration:350,easing:'cubic-bezier(.2,.75,.25,1)'});}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectPlatform(index));tab.addEventListener('keydown',e=>{let next=index;if(e.key==='ArrowRight')next=(index+1)%tabs.length;else if(e.key==='ArrowLeft')next=(index+tabs.length-1)%tabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=tabs.length-1;else return;e.preventDefault();selectPlatform(next);tabs[next].focus();});});

